<template>
  <div class="setting-sidebar map-sidebar">
    <div class="setting-sidebar-item">
      <div class="setting-sidebar-title">
        电子地图
        <el-button
          type="primary"
          size="small"
          class="submit-btn"
          @click="onSaveNodes"
          :loading="saveBtnLoad"
          >保存</el-button
        >
      </div>
      <div class="map-type-box">
        <el-radio-group v-model="model.type" size="mini">
          <el-radio-button
            v-for="item in typeItems"
            :key="item.value"
            :label="item.value"
            >{{ item.label }}</el-radio-button
          >
        </el-radio-group>
      </div>
      <div class="map-sidebar-image" v-if="model.type === 'default'">
        <div
          class="map-sidebar-image-trash"
          v-if="model.image !== ''"
          @click.stop="removeMap"
        >
          <i class="el-icon-delete"></i>
        </div>
        <vr-upload
          uploadClass="img-container"
          ref="imgUploader"
          tip="建议尺寸：500 X 500"
          listType
          :cropImg="false"
          :autoUpload="true"
          :fileList="fileList"
          @onSuccess="onImageUploadSuccess"
        />
      </div>
      <div class="map-sidebar-gaode" v-else-if="model.type === 'gaode'">
        <el-alert type="warning">暂未开放，该功能支持高德地图平台沙盘效果呈现</el-alert>
      </div>
      <div class="map-sidebar-gis" v-else-if="model.type === 'gis'">
        <el-input
          type="textarea"
          v-model="model.imgUrl"
          placeholder="请输入tiles服务地址,一行一个"
        ></el-input>
      </div>
    </div>
    <div class="add-scene-marker" v-if="model.imgUrl !== ''">
      <el-popover
        placement="right"
        width="400"
        trigger="manual"
        @show="getProductScenes"
        v-model="showPopover"
      >
        <el-form ref="form" :rules="rules" :model="form" label-width="80px">
          <el-form-item label="选择场景" prop="sceneId">
            <el-select v-model="form.sceneId" placeholder="请选择选择场景">
              <el-option
                v-for="(scene, index) in noSelectScenes"
                :key="index"
                :label="scene.title"
                :value="scene.id"
              ></el-option>
            </el-select>
          </el-form-item>
          <el-form-item>
            <el-button type="primary" @click.stop="onSubmit">确定</el-button>
          </el-form-item>
        </el-form>
        <div slot="reference" class="map-act-btn-group">
          <div class="map-act-btn" v-if="model.type === 'default'">
            <el-button
              type="success"
              size="mini"
              icon="el-icon-position"
              @click="mapPointConfig('default')"
              >标记全景图中心点</el-button
            >
          </div>
          <div v-if="model.type === 'default'">
            <el-button
              type="primary"
              size="mini"
              icon="el-icon-map-location"
              @click="showPopover = !showPopover"
              >标记场景点位</el-button
            >
          </div>
          <div class="map-act-btn" v-if="model.type === 'gis' && isCompanyUser">
            <el-button
              type="success"
              size="mini"
              icon="el-icon-position"
              @click="mapPointConfig('gis')"
              >标记场景点位</el-button
            >
          </div>
        </div>
      </el-popover>
      <!-- v-if="addMapSceneMarker" -->
    </div>
    <div class="map-nodes">
      <div class="map-node-list">
        <div
          class="map-node-item"
          v-for="(node, index) in mapSceneNodes"
          :class="
            (nowSceneNode && nowSceneNode.sceneId === node.sceneId) ||
            mapSceneNodes.length === 1
              ? 'active'
              : ''
          "
          @click.stop="onChangeScene(node)"
          @mouseover="showDelBtn(index)"
          @mouseout="hideDelBtn(index)"
          :key="index"
        >
          <div class="map-node-item-dot"></div>
          <div class="map-node-item-title">{{ node.sceneTitle }}</div>
          <div
            class="del-btn"
            v-show="showIndexList.indexOf(index) >= 0"
            @click="onDelNode(node)"
          >
            <i class="el-icon el-icon-delete"></i>
          </div>
        </div>
      </div>
      <div class="map-node-tips">
        <div class="el-upload__tip">
          点击标记全景图在电子地图上的坐标：弹出窗口移动坐标器，点击确定后点击右上角保存（电子地图旁边）生效
          <br />
          点击电子点图标记场景点位
        </div>
      </div>
    </div>
  </div>
</template>
  <script>
import { getProductScenes } from '@/api/vr'
import { getGisTilesImageUrl } from '@/api/iot'
import { getCurrentUser } from '@/api/user'
export default {
  name: 'MapSidebar',
  components: {
    VrUpload: () => import('@/components/VrUpload.vue'),
  },
  props: {
    productId: undefined,
    mapSceneNodes: {
      type: Array,
      default() {
        return []
      },
    },
    activeNode: {
      type: Object,
      default() {
        return null
      },
    },
  },
  data() {
    return {
      model: {
        type: 'default',
        imgUrl: '',
        gisParam: '',
      },
      typeItems: [
        {
          label: '平面图',
          value: 'default',
        },
        {
          label: '高德地图',
          value: 'gaode',
        }
      ],
      fileList: [],
      addMapSceneMarker: false,
      form: {
        sceneId: undefined,
      },
      showPopover: false,
      scenes: [],
      showIndexList: [],
      nowSceneNode: null,
      rules: {
        sceneId: [{ required: true, message: '请选择场景', trigger: 'change' }],
      },
      saveBtnLoad: false,
      planeGraph: null,
      isCompanyUser: false
    }
  },
  watch: {
    // eslint-disable-next-line no-unused-vars
    activeNode(newVal, oldVal) {
      // console.log('nel:', newVal)
      if (oldVal && newVal && newVal.sceneId !== oldVal.sceneId) {
        this.nowSceneNode = newVal
      }
    },
    'model.type': {
      handler(newVal, oldVal) {
        if (oldVal === 'default') {
          this.model.imgUrl = ''
        }
        if (newVal === 'gis' && !this.model.imgUrl) {
          this.companyMergeGisTilesImageUrl()
        }
        this.$emit('onMapChangeType', newVal, oldVal)
      },
    },
  },
  computed: {
    noSelectScenes() {
      return this.scenes.filter(
        (item) =>
          this.mapSceneNodes.findIndex((node) => node.sceneId === item.id) < 0
      )
    },
  },
  async created() {
    this.nowSceneNode = this.activeNode
    const vipInfo = await getCurrentUser()
    if (vipInfo.role === '1' && vipInfo.company) {
      this.isCompanyUser = true
      this.typeItems.push({
          label: 'IotGis',
          value: 'gis',
        })
    }

  },
  mounted() {},
  methods: {
    mapPointConfig(type = 'default') {
      if ('gis' === type && !this.model.imgUrl) {
        return this.$message.error('请先填写GIS地图 Tiles URL')
      }
      this.$emit('onMarkerCenterMapPoint', type, this.model.imgUrl)
    },
    async getProductScenes() {
      this.scenes = await getProductScenes(this.productId)
    },
    onImageUploadSuccess(data) {
      this.model.imgUrl = data.path
      this.$set(this.model, 'image', data.path)
      this.$emit('onAddMapImage', data.url)
    },
    async init(planeGraph) {
      // eslint-disable-next-line no-undef
      this.planeGraph = planeGraph
      this.model.type = planeGraph.type
      if (planeGraph) {
        if (planeGraph.type === 'default') {
          this.model.imgUrl = planeGraph.imgUrl
          this.fileList = [
            {
              name: '平面图',
              url: planeGraph.imgUrlFull,
              path: planeGraph.imgUrl,
            },
          ]
          this.$refs.imgUploader.initFileList(this.fileList)
        } else {
          if (planeGraph.imgUrl) {
            this.model.imgUrl = planeGraph.imgUrl
          } else {
            this.companyMergeGisTilesImageUrl()
          }
        }
      } else {
        this.companyMergeGisTilesImageUrl()
      }
    },
    removeMap() {
      this.model.imgUrl = ''
      this.fileList = []
      this.$refs.imgUploader.clear()
      this.nowSceneNode = null
      this.$emit('onRemoveMap')
    },
    showDelBtn(index) {
      this.showIndexList.push(index)
    },
    hideDelBtn(index) {
      this.showIndexList.splice(this.showIndexList.indexOf(index), 1)
    },
    onChangeScene(sceneNode) {
      this.nowSceneNode = sceneNode
      this.$emit('onMapChangeScene', sceneNode)
    },
    onDelNode(node) {
      this.$emit('onRemoveMapSceneMarker', node)
    },
    onSubmit() {
      this.$refs.form.validate((valid) => {
        if (valid) {
          this.onAddMapSceneMarker()
        }
      })
    },
    findSceneById(sceneId) {
      const index = this.scenes.findIndex((item) => item.id === sceneId)
      if (index >= 0) {
        return this.scenes[index]
      }

      return null
    },
    onAddMapSceneMarker() {
      this.addMapSceneMarker = true
      this.showPopover = false
      const scene = this.findSceneById(this.form.sceneId)
      this.$emit('onAddMapSceneMarker', {
        prevMapNode: this.activeNode,
        addMapSceneMarker: this.addMapSceneMarker,
        sceneId: this.form.sceneId,
        sceneTitle: scene ? scene.title : '',
      })
      this.form.sceneId = undefined
    },
    onSaveNodes() {
      this.saveBtnLoad = true
      // , this.nowSceneNode
      this.$emit('onSaveMapSceneMarkers', this.model)
    },
    async companyMergeGisTilesImageUrl() {
      if (this.isCompanyUser) {
        const tilesData = await getGisTilesImageUrl()
        if (tilesData && 'tiles' in tilesData) {
          this.model.gisParam = tilesData
          this.model.imgUrl = tilesData.tiles.urls.join('\n')
        }
        // TODO: 获取企业-iot-tiles-url
        // const imgm = window.L.tileLayer.chinaProvider('GaoDe.Satellite.Map', options)
        // const imga = window.L.tileLayer.chinaProvider('GaoDe.Satellite.Annotion', options)
        // const image = window.L.layerGroup([imgm, imga])
      }
    },
  },
}
</script>
