import request from '@/utils/request'

export function getDeviceCatalogs(query) {
  return request({
    url: '/iot/device/catalogs',
    method: 'get',
    params: query,
  })
}

export function getDeviceList(query) {
  return request({
    url: '/iot/device/list',
    method: 'get',
    params: query,
  })
}

export function getDeviceInfo(code) {
  return request({
    url: `/iot/device/info/${code}`,
    method: 'get',
  })
}

export function getDeviceRealData(code) {
  return request({
    url: `/iot/device/real-data/${code}`,
    method: 'get',
  })
}

export function getDeviceHistoryData(code, query) {
  return request({
    url: `/iot/device/history-data/${code}`,
    method: 'get',
    params: query,
  })
}

export function getCameraLiveUrl(code) {
  return request({
    url: `/iot/camera/live-url/${code}`,
    method: 'get',
  })
}

export function getGisTilesImageUrl() {
  return request({
    url: '/iot/gis/tiles-url',
    method: 'get',
  })
}

